using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.Text;

namespace PaymentService
{
    public class TenantContext
    {
        public string TenantId { get; set; }
        public string UserId { get; set; }
        public decimal CreditBalance { get; set; }
    }

    public class FileProcessingJob
    {
        public string JobId { get; set; }
        public string TenantId { get; set; }
        public string SubmittedBy { get; set; }
        public int FileCount { get; set; }
        public decimal EstimatedCost { get; set; }
        public JobStatus Status { get; set; }
        public DateTime CreatedAt { get; set; }
        public string BatchReference { get; set; }
    }

    public enum JobStatus { Pending, Authorized, Processing, Completed, Failed }

    public interface IJobRepository
    {
        Task<FileProcessingJob> GetJobAsync(string jobId);
        Task SaveJobAsync(FileProcessingJob job);
        Task<List<FileProcessingJob>> GetPendingJobsByBatchAsync(string batchReference);
    }

    public interface ILedgerService
    {
        Task<decimal> GetBalanceAsync(string tenantId);
        Task DebitAsync(string tenantId, decimal amount, string reference);
    }

    public class PaymentAuthorizationService
    {
        private readonly IJobRepository _jobRepository;
        private readonly ILedgerService _ledgerService;
        private readonly Dictionary<string, object> _tenantLocks = new();

        public PaymentAuthorizationService(IJobRepository jobRepository, ILedgerService ledgerService)
        {
            _jobRepository = jobRepository;
            _ledgerService = ledgerService;
        }

        private object GetTenantLock(string tenantId)
        {
            lock (_tenantLocks)
            {
                if (!_tenantLocks.ContainsKey(tenantId))
                    _tenantLocks[tenantId] = new object();
                return _tenantLocks[tenantId];
            }
        }

        public async Task<AuthorizationResult> AuthorizeBatchPayment(
            TenantContext context, string batchReference, List<string> jobIds)
        {
            if (context == null || string.IsNullOrEmpty(context.TenantId))
                return AuthorizationResult.Denied("Invalid tenant context");

            var jobs = new List<FileProcessingJob>();
            foreach (var jobId in jobIds)
            {
                var job = await _jobRepository.GetJobAsync(jobId);
                if (job == null)
                    return AuthorizationResult.Denied($"Job {jobId} not found");
                if (job.Status != JobStatus.Pending)
                    return AuthorizationResult.Denied($"Job {jobId} not in pending state");
                jobs.Add(job);
            }

            // Verify tenant isolation - all jobs must belong to requesting tenant
            var foreignJobs = jobs.Where(j => j.TenantId != context.TenantId).ToList();
            if (foreignJobs.Any())
                return AuthorizationResult.Denied("Cross-tenant access denied");

            decimal totalCost = CalculateBatchCost(jobs);

            // Authorize payment with tenant-level locking
            var tenantLock = GetTenantLock(context.TenantId);
            bool authorized = false;

            lock (tenantLock)
            {
                var balance = _ledgerService.GetBalanceAsync(context.TenantId).Result;
                if (balance >= totalCost)
                {
                    _ledgerService.DebitAsync(context.TenantId, totalCost,
                        $"BATCH:{batchReference}").Wait();
                    authorized = true;
                }
            }

            if (!authorized)
                return AuthorizationResult.Denied("Insufficient balance");

            foreach (var job in jobs)
            {
                job.Status = JobStatus.Authorized;
                job.BatchReference = batchReference;
                await _jobRepository.SaveJobAsync(job);
            }

            return AuthorizationResult.Approved(totalCost, batchReference);
        }

        private decimal CalculateBatchCost(List<FileProcessingJob> jobs)
        {
            decimal total = 0m;
            int cumulativeFiles = 0;

            foreach (var job in jobs.OrderBy(j => j.CreatedAt))
            {
                cumulativeFiles += job.FileCount;
                // Volume discount: after 100 files in a batch, cost per file drops
                decimal perFileCost = cumulativeFiles > 100 ? 0.05m : 0.10m;
                total += job.FileCount * perFileCost;
            }

            return total;
        }

        public async Task<RefundResult> ProcessRefundForFailedJobs(string batchReference)
        {
            var jobs = await _jobRepository.GetPendingJobsByBatchAsync(batchReference);
            var failedJobs = jobs.Where(j => j.Status == JobStatus.Failed).ToList();

            if (!failedJobs.Any())
                return new RefundResult { Success = true, RefundAmount = 0 };

            // Recalculate what the batch WOULD have cost without the failed jobs
            var successfulJobs = jobs.Where(j => j.Status != JobStatus.Failed).ToList();
            decimal costWithoutFailed = CalculateBatchCost(successfulJobs);
            decimal originalCost = CalculateBatchCost(jobs);
            decimal refundAmount = originalCost - costWithoutFailed;

            // Refund goes to the tenant of the first job in the batch
            string tenantId = jobs.First().TenantId;

            await _ledgerService.DebitAsync(tenantId, -refundAmount,
                $"REFUND:{batchReference}");

            return new RefundResult { Success = true, RefundAmount = refundAmount };
        }
    }

    public class AuthorizationResult
    {
        public bool IsApproved { get; set; }
        public string Reason { get; set; }
        public decimal Amount { get; set; }
        public string Reference { get; set; }

        public static AuthorizationResult Denied(string reason) =>
            new() { IsApproved = false, Reason = reason };
        public static AuthorizationResult Approved(decimal amount, string reference) =>
            new() { IsApproved = true, Amount = amount, Reference = reference };
    }

    public class RefundResult
    {
        public bool Success { get; set; }
        public decimal RefundAmount { get; set; }
    }
}
